from typing import List

class Solution:
    def shortestBridge(self, grid: List[List[int]]) -> int:
        n = len(grid)

        # Find the first island using DFS
        def dfs(r, c):
            stack = [(r, c)]
            grid[r][c] = 2  # Mark as visited and part of first island
            while stack:
                curr_r, curr_c = stack.pop()
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = curr_r + dr, curr_c + dc
                    if 0 <= nr < n and 0 <= nc < n and grid[nr][nc] == 1:
                        grid[nr][nc] = 2
                        stack.append((nr, nc))

        # Find the first island's boundary cells for BFS
        def find_first_island():
            for i in range(n):
                for j in range(n):
                    if grid[i][j] == 1:
                        dfs(i, j)
                        return

        find_first_island()

        # Collect all cells of the first island (marked as 2) into a queue for BFS
        queue = deque()
        for i in range(n):
            for j in range(n):
                if grid[i][j] == 2:
                    queue.append((i, j))

        # BFS to find the shortest path to the second island (marked as 1)
        steps = 0
        while queue:
            size = len(queue)
            for _ in range(size):
                r, c = queue.popleft()
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if grid[nr][nc] == 1:
                            return steps
                        elif grid[nr][nc] == 0:
                            grid[nr][nc] = 2  # Mark as visited
                            queue.append((nr, nc))
            steps += 1

        return -1

